//BasicComplexVector res1 = (BasicComplexVector)conn.run("getFFT", args);

//3. 获取返回的复数结果
//DolphinDB中用两个浮点来保存复数, Double2类型包含x实数，y虚数两个部分。
List<Double2> v = res.getDataArray();
System.Console.WriteLine(v[0].x); //实部
System.Console.WriteLine(v[0].y); //虚部

